  88:     rem.u32 %r_wo, %r_rem0, %rWout;
  89:     div.u32 %r_rem1, %r_rem0, %rWout;
  90:     rem.u32 %r_ho, %r_rem1, %rHout;
  91:     div.u32 %r_rem2, %r_rem1, %rHout;
  92:     rem.u32 %r_co, %r_rem2, %rCout;
  93:     div.u32 %r_n,  %r_rem2, %rCout;
  94:     // Compute base thread id for the CTA and derive co0 (Cout index shared by most threads in the block)
  95:     mul.lo.u32 %r_btid, %r_cta, %r_tmp1;          // base tid of CTA
  96:     mov.u32 %r_rem0, %r_btid;
  97:     // wo0 = btid % Wout
  98:     rem.u32 %r_t0, %r_rem0, %rWout;
  99:     div.u32 %r_rem1, %r_rem0, %rWout;
 100:     // ho0 = rem1 % Hout
 101:     rem.u32 %r_t1, %r_rem1, %rHout;
 102:     div.u32 %r_rem2, %r_rem1, %rHout;
 103:     // co0 = rem2 % Cout
 104:     rem.u32 %r_co0, %r_rem2, %rCout;
 105:     // n0 = rem2 / Cout (unused)
 106:     // Cooperative staging of weights for co0 into shared memory
 107:     mul.lo.u32 %r_cksz, %rKH, %rKW;               // KH*KW
 108:     mul.lo.u32 %r_total_w, %rCin, %r_cksz;        // Cin*KH*KW
 109:     mov.u64 %rd_smem_base, smem_w;
 110:     // Vectorized cp.async staging: 16B copies for main, 4B for tail
 111:     // r_wco_base = co0 * total_w
 112:     mul.lo.u32 %r_wco_base, %r_co0, %r_total_w;
 113:     // total_w4 = (total_w >> 2) << 2
 114:     shr.u32 %r_t0, %r_total_w, 2;
 115:     shl.b32 %r_total_w4, %r_t0, 2;
 116:     // step4 = blockDim.x * 4
 117:     shl.b32 %r_step4, %r_tmp1, 2;
 118:     // load_idx4 = tid.x * 4
 119:     shl.b32 %r_load_idx4, %r_tmp0, 2;
 120: L_sload_vec:
 121:     setp.ge.u32 %p, %r_load_idx4, %r_total_w4;
 122:     @%p bra L_sload_vec_done;
 123:     // Global address for 16B chunk
 124:     add.u32 %r_t2, %r_wco_base, %r_load_idx4;
 125:     mul.wide.u32 %ofs_bytes, %r_t2, 4;
 126:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 127:     // Shared memory address for 16B chunk
 128:     mul.wide.u32 %ofs_bytes, %r_load_idx4, 4;
 129:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 130:     cp.async.ca.shared.global [%addr_smem], [%addr_w], 16;
 131:     add.u32 %r_load_idx4, %r_load_idx4, %r_step4;
 132:     bra L_sload_vec;
 133: L_sload_vec_done:
 134:     // Tail: 4B cp.async for remaining elements
 135:     add.u32 %r_load_idx, %r_total_w4, %r_tmp0;
 136: L_sload_tail:
 137:     setp.ge.u32 %p, %r_load_idx, %r_total_w;
 138:     @%p bra L_sload_done;
 139:     add.u32 %r_t2, %r_wco_base, %r_load_idx;
 140:     mul.wide.u32 %ofs_bytes, %r_t2, 4;
 141:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 142:     mul.wide.u32 %ofs_bytes, %r_load_idx, 4;
 143:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 144:     cp.async.ca.shared.global [%addr_smem], [%addr_w], 4;
 145:     add.u32 %r_load_idx, %r_load_idx, %r_tmp1;
 146:     bra L_sload_tail;
 147: L_sload_done:
 148:     // Commit and wait for async copies before proceeding
 149:     cp.async.commit_group;
 150:     cp.async.wait_group 0;
 151:     bar.sync 0;
 152:     // Early-exit after cooperative weight staging to avoid barrier divergence
 153:     setp.ge.u32 %p_exit, %r_tid, %r_total;
 154:     @%p_exit bra DONE;
 155:     // acc = bias[co]
 156:     mul.wide.u32 %ofs_bytes, %r_co, 4;
 157:     add.s64 %addr_bias, %rd_b, %ofs_bytes;
 158:     ld.global.f32 %f_bias, [%addr_bias];
 159:     mov.f32 %f_acc, %f_bias;
 160:     // wbase = (int)wo * stride_w - (int)pad_w
 161:     mul.lo.u32 %r_t0, %r_wo, %rSw;
 162:     cvt.s32.u32 %r_t1, %r_t0;
 163:     cvt.s32.u32 %r_t2, %rPw;
 164:     sub.s32 %r_wbase_s32, %r_t1, %r_t2;
 165:     // hbase = (int)ho * stride_h - (int)pad_h
 166:     mul.lo.u32 %r_t0, %r_ho, %rSh;
 167:     cvt.s32.u32 %r_t1, %r_t0;
 168:     cvt.s32.u32 %r_t2, %rPh;
 169:     sub.s32 %r_hbase_s32, %r_t1, %r_t2;
 170:     // Determine if this thread shares co with CTA base (enables shared-memory weights)
 171:     setp.eq.u32 %p_same, %r_co, %r_co0;
 172:     // Fast path if Cin == 3: unroll channel loop
 173:     setp.eq.u32 %p_cin3, %rCin, 3;
 174:     @%p_cin3 bra L_fast_cin3;
 175:     // Loop over input channels c (generic path)
 176:     mov.u32 %r_c, 0;
 177: L_c_loop:
 178:     setp.ge.u32 %p, %r_c, %rCin;
 179:     @%p bra L_end_c;
 180:     // (co*Cin + c)
 181:     mul.lo.u32 %r_w_cc, %r_co, %rCin;
 182:     add.u32 %r_w_cc, %r_w_cc, %r_c;
 183:     // idx_nc = n*Cin + c
 184:     mul.lo.u32 %r_idx_nc, %r_n, %rCin;
 185:     add.u32 %r_idx_nc, %r_idx_nc, %r_c;
 186:     // Loop over kernel height kh
 187:     mov.u32 %r_kh, 0;
 188: L_kh_loop:
 189:     setp.ge.u32 %p, %r_kh, %rKH;
 190:     @%p bra L_end_kh;
 191:     // h_in = hbase + kh
 192:     cvt.s32.u32 %r_t0, %r_kh;
 193:     add.s32 %r_hin_s32, %r_hbase_s32, %r_t0;
 194:     // if (h_in < 0 || h_in >= Hin) skip inner loop
 195:     setp.lt.s32 %p, %r_hin_s32, 0;
 196:     @%p bra L_skip_h;
 197:     cvt.s32.u32 %r_t1, %rHin;
 198:     setp.ge.s32 %p, %r_hin_s32, %r_t1;
 199:     @%p bra L_skip_h;
 200:     // in_base = ((idx_nc * Hin) + (u32)h_in) * Win
 201:     mul.lo.u32 %r_idx_nch, %r_idx_nc, %rHin;
 202:     cvt.u32.s32 %r_t2, %r_hin_s32;
 203:     add.u32 %r_idx_nch, %r_idx_nch, %r_t2;
 204:     mul.lo.u32 %r_in_base, %r_idx_nch, %rWin;
 205:     // w_base_idx for global path: (((co*Cin + c) * KH) + kh) * KW
 206:     mul.lo.u32 %r_w_cch, %r_w_cc, %rKH;
 207:     add.u32 %r_w_cch, %r_w_cch, %r_kh;
 208:     mul.lo.u32 %r_w_base_idx, %r_w_cch, %rKW;
 209:     // w_local_base_idx for shared path: (((c) * KH) + kh) * KW
 210:     mul.lo.u32 %r_t3, %r_c, %rKH;
 211:     add.u32 %r_t3, %r_t3, %r_kh;
 212:     mul.lo.u32 %r_w_local_base_idx, %r_t3, %rKW;
 213:     // Compute valid kw range to avoid per-iteration bounds checks
 214:     // kw_lo = max(0, -wbase); kw_hi = min(KW, Win - wbase)
 215:     mov.u32 %r_kw_lo, 0;
 216:     setp.lt.s32 %p, %r_wbase_s32, 0;
 217:     sub.s32 %r_tmpk0, 0, %r_wbase_s32;
 218:     cvt.u32.s32 %r_tmpk1, %r_tmpk0;
 219:     @!%p bra L_kwlo_done;
 220:     setp.gt.u32 %p, %r_tmpk1, %rKW;
 221:     @%p mov.u32 %r_kw_lo, %rKW;
 222:     @!%p mov.u32 %r_kw_lo, %r_tmpk1;
 223:     bra L_kwlo_done;
 224: L_kwlo_done:
 225:     cvt.s32.u32 %r_t4, %rWin;
 226:     sub.s32 %r_tmpk0, %r_t4, %r_wbase_s32;
 227:     setp.le.s32 %p, %r_tmpk0, 0;
 228:     @%p mov.u32 %r_kw_hi, 0;
 229:     @%p bra L_kwhi_done;
 230:     cvt.u32.s32 %r_tmpk1, %r_tmpk0;
 231:     setp.gt.u32 %p, %r_tmpk1, %rKW;
 232:     @%p mov.u32 %r_kw_hi, %rKW;
 233:     @!%p mov.u32 %r_kw_hi, %r_tmpk1;
 234: L_kwhi_done:
 235:     // Loop over kernel width kw in [kw_lo, kw_hi)
 236:     mov.u32 %r_kw, %r_kw_lo;
 237: L_kw_loop:
 238: L_kw_vec_loop:
 239:     // If we have at least 4 elements remaining, and input address is 16B-aligned, use vectorized loads
 240:     add.u32 %r_kwp4, %r_kw, 4;
 241:     setp.gt.u32 %p, %r_kwp4, %r_kw_hi;
 242:     @%p bra L_kw_scalar_entry;
 243:     // Compute E = in_base + (wbase + kw) and check 16B alignment (E % 4 == 0)
 244:     cvt.s32.u32 %r_t3, %r_kw;
 245:     add.s32 %r_win_s32, %r_wbase_s32, %r_t3;
 246:     cvt.u32.s32 %r_win_u32, %r_win_s32;
 247:     add.u32 %r_t5, %r_in_base, %r_win_u32; // E
 248:     and.b32 %r_align, %r_t5, 3;
 249:     setp.ne.u32 %p, %r_align, 0;
 250:     @%p bra L_kw_scalar_entry;
 251:     // Vectorized load of 4 input values
 252:     mul.wide.u32 %ofs_bytes, %r_t5, 4;
 253:     add.s64 %addr_inp, %rd_inp, %ofs_bytes;
 254:     ld.global.v4.f32 {%f_in, %f_v1, %f_v2, %f_v3}, [%addr_inp];
 255:     // Prepare base indices for weights
 256:     add.u32 %r_wloc_base_kw, %r_w_local_base_idx, %r_kw;
 257:     add.u32 %r_wglob_base_kw, %r_w_base_idx, %r_kw;
 258:     // Load 4 weights (shared if same co, else global) and accumulate
 259:     // k = 0
 260:     add.u32 %r_t0, %r_wloc_base_kw, 0;
 261:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 262:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 263:     add.u32 %r_t0, %r_wglob_base_kw, 0;
 264:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 265:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 266:     @%p_same ld.shared.f32 %f_w0, [%addr_smem];
 267:     @!%p_same ld.global.f32 %f_w0, [%addr_w];
 268:     // k = 1
 269:     add.u32 %r_t0, %r_wloc_base_kw, 1;
 270:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 271:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 272:     add.u32 %r_t0, %r_wglob_base_kw, 1;
 273:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 274:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 275:     @%p_same ld.shared.f32 %f_w1, [%addr_smem];
 276:     @!%p_same ld.global.f32 %f_w1, [%addr_w];
 277:     // k = 2
 278:     add.u32 %r_t0, %r_wloc_base_kw, 2;
 279:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 280:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 281:     add.u32 %r_t0, %r_wglob_base_kw, 2;
 282:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 283:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 284:     @%p_same ld.shared.f32 %f_w2, [%addr_smem];
 285:     @!%p_same ld.global.f32 %f_w2, [%addr_w];
 286:     // k = 3
 287:     add.u32 %r_t0, %r_wloc_base_kw, 3;
 288:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 289:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 290:     add.u32 %r_t0, %r_wglob_base_kw, 3;
 291:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 292:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 293:     @%p_same ld.shared.f32 %f_w3, [%addr_smem];
 294:     @!%p_same ld.global.f32 %f_w3, [%addr_w];
 295:     // Accumulate 4 FMAs
 296:     fma.rn.f32 %f_acc, %f_in,  %f_w0, %f_acc;
 297:     fma.rn.f32 %f_acc, %f_v1,  %f_w1, %f_acc;
 298:     fma.rn.f32 %f_acc, %f_v2,  %f_w2, %f_acc;
 299:     fma.rn.f32 %f_acc, %f_v3,  %f_w3, %f_acc;
 300:     // Advance kw by 4 and continue vector loop
 301:     add.u32 %r_kw, %r_kw, 4;
 302:     bra L_kw_vec_loop;
 303: L_kw_scalar_entry:
 304: L_kw_scalar_loop:
 305:     setp.ge.u32 %p, %r_kw, %r_kw_hi;
 306:     @%p bra L_end_kw;
 307:     // Scalar iteration for remaining kw values
 308:     cvt.s32.u32 %r_t3, %r_kw;
 309:     add.s32 %r_win_s32, %r_wbase_s32, %r_t3;
 310:     cvt.u32.s32 %r_win_u32, %r_win_s32;
 311:     add.u32 %r_t5, %r_in_base, %r_win_u32;
 312:     mul.wide.u32 %ofs_bytes, %r_t5, 4;
 313:     add.s64 %addr_inp, %rd_inp, %ofs_bytes;
 314:     ld.global.f32 %f_in, [%addr_inp];
 315:     // Shared-memory address for weights: smem_w[w_local_base_idx + kw]
 316:     add.u32 %r_t0, %r_w_local_base_idx, %r_kw;
 317:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 318:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 319:     // Global-memory address for weights: w[w_base_idx + kw]
 320:     add.u32 %r_t0, %r_w_base_idx, %r_kw;
 321:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 322:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 323:     @%p_same ld.shared.f32 %f_w, [%addr_smem];
 324:     @!%p_same ld.global.f32 %f_w,  [%addr_w];
 325:     fma.rn.f32 %f_acc, %f_in, %f_w, %f_acc;
 326:     add.u32 %r_kw, %r_kw, 1;
 327:     bra L_kw_scalar_loop;
 328: L_end_kw:
 329: L_skip_h:
 330:     add.u32 %r_kh, %r_kh, 1;
 331:     bra L_kh_loop;
 332: L_end_kh:
 333:     add.u32 %r_c, %r_c, 1;
 334:     bra L_c_loop;
 335: L_end_c:
 336: L_store:
 337:     // Store result to output: ((((n*Cout)+co)*Hout + ho)*Wout + wo)
 338:     mul.lo.u32 %r_t0, %r_n, %rCout;
 339:     add.u32 %r_t0, %r_t0, %r_co;
 340:     mul.lo.u32 %r_t0, %r_t0, %rHout;
 341:     add.u32 %r_t0, %r_t0, %r_ho;
 342:     mul.lo.u32 %r_t0, %r_t0, %rWout;
 343:     add.u32 %r_t0, %r_t0, %r_wo;
 344:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 345:     add.s64 %addr_out, %rd_out, %ofs_bytes;
 346:     st.global.f32 [%addr_out], %f_acc;
 347:     bra DONE;
 348:     // Fast path for Cin==3, unrolled over channels
 349: L_fast_cin3:
 350:     // Precompute n*Cin base
 351:     mul.lo.u32 %r_idx_nc_base, %r_n, %rCin; // Cin is 3 here
 352:     // Loop over kernel height kh
 353:     mov.u32 %r_kh, 0;
 354: L_kh_loop_f:
 355:     setp.ge.u32 %p, %r_kh, %rKH;
 356:     @%p bra L_end_kh_f;
 357:     // h_in = hbase + kh
 358:     cvt.s32.u32 %r_t0, %r_kh;
 359:     add.s32 %r_hin_s32, %r_hbase_s32, %r_t0;
 360:     // Bounds check on h_in
 361:     setp.lt.s32 %p, %r_hin_s32, 0;
 362:     @%p bra L_skip_h_f;
 363:     cvt.s32.u32 %r_t1, %rHin;
 364:     setp.ge.s32 %p, %r_hin_s32, %r_t1;
 365:     @%p bra L_skip_h_f;
 366:     // Compute in_base for c0,c1,c2
 367:     cvt.u32.s32 %r_t2, %r_hin_s32;
 368:     // c0
 369:     mul.lo.u32 %r_idx_nch_c0, %r_idx_nc_base, %rHin;
 370:     add.u32 %r_idx_nch_c0, %r_idx_nch_c0, %r_t2;
 371:     mul.lo.u32 %r_in_base_c0, %r_idx_nch_c0, %rWin;
 372:     // c1
 373:     add.u32 %r_t0, %r_idx_nc_base, 1;
 374:     mul.lo.u32 %r_idx_nch_c1, %r_t0, %rHin;
 375:     add.u32 %r_idx_nch_c1, %r_idx_nch_c1, %r_t2;
 376:     mul.lo.u32 %r_in_base_c1, %r_idx_nch_c1, %rWin;
 377:     // c2
 378:     add.u32 %r_t0, %r_idx_nc_base, 2;
 379:     mul.lo.u32 %r_idx_nch_c2, %r_t0, %rHin;
 380:     add.u32 %r_idx_nch_c2, %r_idx_nch_c2, %r_t2;
 381:     mul.lo.u32 %r_in_base_c2, %r_idx_nch_c2, %rWin;
 382:     // Compute weight base indices for c0,c1,c2 (global and shared-local)
 383:     mul.lo.u32 %r_t0, %r_co, %rCin; // co*Cin
 384:     // c0
 385:     add.u32 %r_t1, %r_t0, 0;
 386:     mul.lo.u32 %r_t1, %r_t1, %rKH;
 387:     add.u32 %r_t1, %r_t1, %r_kh;
 388:     mul.lo.u32 %r_w_base_idx_c0, %r_t1, %rKW;
 389:     mul.lo.u32 %r_t3, 0, %rKH;
 390:     add.u32 %r_t3, %r_t3, %r_kh;
 391:     mul.lo.u32 %r_w_local_base_idx_c0, %r_t3, %rKW;
 392:     // c1
 393:     add.u32 %r_t1, %r_t0, 1;
 394:     mul.lo.u32 %r_t1, %r_t1, %rKH;
 395:     add.u32 %r_t1, %r_t1, %r_kh;
 396:     mul.lo.u32 %r_w_base_idx_c1, %r_t1, %rKW;
 397:     mul.lo.u32 %r_t3, 1, %rKH;
 398:     add.u32 %r_t3, %r_t3, %r_kh;
 399:     mul.lo.u32 %r_w_local_base_idx_c1, %r_t3, %rKW;
 400:     // c2
 401:     add.u32 %r_t1, %r_t0, 2;
 402:     mul.lo.u32 %r_t1, %r_t1, %rKH;
 403:     add.u32 %r_t1, %r_t1, %r_kh;
 404:     mul.lo.u32 %r_w_base_idx_c2, %r_t1, %rKW;
 405:     mul.lo.u32 %r_t3, 2, %rKH;
 406:     add.u32 %r_t3, %r_t3, %r_kh;
 407:     mul.lo.u32 %r_w_local_base_idx_c2, %r_t3, %rKW;
 408:     // Compute valid kw range once per kh
 409:     mov.u32 %r_kw_lo, 0;
 410:     setp.lt.s32 %p, %r_wbase_s32, 0;
 411:     sub.s32 %r_tmpk0, 0, %r_wbase_s32;
 412:     cvt.u32.s32 %r_tmpk1, %r_tmpk0;
 413:     @!%p bra L_kwlo_done_f;
 414:     setp.gt.u32 %p, %r_tmpk1, %rKW;
 415:     @%p mov.u32 %r_kw_lo, %rKW;
 416:     @!%p mov.u32 %r_kw_lo, %r_tmpk1;
 417:     bra L_kwlo_done_f;
 418: L_kwlo_done_f:
 419:     cvt.s32.u32 %r_t4, %rWin;
 420:     sub.s32 %r_tmpk0, %r_t4, %r_wbase_s32;
 421:     setp.le.s32 %p, %r_tmpk0, 0;
 422:     @%p mov.u32 %r_kw_hi, 0;
 423:     @%p bra L_kwhi_done_f;
 424:     cvt.u32.s32 %r_tmpk1, %r_tmpk0;
 425:     setp.gt.u32 %p, %r_tmpk1, %rKW;
 426:     @%p mov.u32 %r_kw_hi, %rKW;
 427:     @!%p mov.u32 %r_kw_hi, %r_tmpk1;
 428: L_kwhi_done_f:
 429:     // Loop over kw with vectorized inner when possible
 430:     mov.u32 %r_kw, %r_kw_lo;
 431: L_kw_loop_f:
 432: L_kw_vec_loop_f:
 433:     add.u32 %r_kwp4, %r_kw, 4;
 434:     setp.gt.u32 %p, %r_kwp4, %r_kw_hi;
 435:     @%p bra L_kw_scalar_entry_f;
